_DURATION_RE = re.compile(
    r"\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*\Z"
)
_MULTIPLIERS = (86400, 3600, 60, 1)


def parse_duration(s):
    """Convert a duration string such as '1h30m' to an integer number of seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _DURATION_RE.fullmatch(s)
    if match is None or not any(part is not None for part in match.groups()):
        raise ValueError(f"invalid duration: {s!r}")

    return sum(
        int(amount) * multiplier
        for amount, multiplier in zip(match.groups(), _MULTIPLIERS)
        if amount is not None
    )
